  z-index: 1000;
  border-radius: 4px;
}
.skip-link:focus { left: 12px; top: 12px; }

.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 48px 24px;
}

.page-title {
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0 0 24px;
  letter-spacing: -0.01em;
}

.preview {
  margin: 0;
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}

.preview-frame {
  width: 100%;
  aspect-ratio: 8 / 5;
  background: #000;
  display: block;
}
.preview-frame svg { width: 100%; height: 100%; display: block; }

.preview-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 14px 18px;
  border-top: 1px solid var(--border);
  background: var(--bg-1);
}
.meta-title { font-weight: 600; font-size: 0.95rem; }
.meta-sub { color: var(--text-muted); font-size: 0.85rem; }

.actions {
  display: flex;
  gap: 12px;
  margin-top: 20px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border-radius: 8px;
  border: 1px solid transparent;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.05s;
  color: var(--text);
}
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn-secondary {
  background: var(--bg-2);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--bg-3); }

.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.btn-danger:hover { background: var(--danger-hover); border-color: var(--danger-hover); }

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(5, 7, 12, 0.72);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 100;
  animation: fadeIn 0.18s ease-out;
}

.dialog-backdrop[hidden] { display: none; }

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes popIn {
  from { opacity: 0; transform: translateY(8px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

.dialog {
  position: relative;
  background: var(--bg-2);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 440px;
  padding: 28px 28px 24px;
  animation: popIn 0.2s ease-out;
}

.dialog-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--danger-soft);
  color: var(--danger);
  margin-bottom: 16px;
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.dialog-desc {
  margin: 0 0 24px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.dialog-desc strong { color: var(--text); font-weight: 600; }

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.dialog-close {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 6px;
  color: var(--text-muted);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.dialog-close:hover { background: var(--bg-3); color: var(--text); }
.dialog-close:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--bg-3);
  color: var(--text);
  padding: 12px 18px;
  border-radius: 8px;
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  z-index: 200;
  font-size: 0.9rem;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop, .dialog, .toast { animation: none; transition: none; }
}
